<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?>
<div id="wrapper"><div class="content"><?php $this->load->view('_navigation'); ?>
<?php $active = array_values(array_filter($items, function($x){return (int)$x['is_active'] === 1;})); $total=count($active); $complete=0; foreach($active as $x){if(isset($checked[(int)$x['id']]))$complete++;} $percent=$total?(int)round($complete*100/$total):0; ?>
<div class="sdp-daily-shell"><div class="sdp-daily-hero"><div><span class="sdp-eyebrow"><i class="fa fa-calendar-check-o"></i> DAILY PRODUCTIVITY</span><h1>My Daily Reminders</h1><p>Follow your daily routine, check off completed responsibilities, and submit your work report.</p></div><div class="sdp-daily-hero-actions"><a class="btn btn-default" href="<?php echo admin_url('smart_daily_productivity/my_day'); ?>"><i class="fa fa-file-text-o"></i> Submit Daily Report</a><a class="btn btn-default" href="<?php echo admin_url('smart_daily_productivity/reminders'); ?>"><i class="fa fa-bell"></i> Audio Alarms</a></div></div>
<div class="sdp-daily-summary"><div><span>Completed today</span><strong><?php echo $complete; ?> <small>/ <?php echo $total; ?></small></strong></div><div><span>Daily progress</span><strong><?php echo $percent; ?>%</strong></div><div><span>Remaining tasks</span><strong><?php echo max(0,$total-$complete); ?></strong></div></div>
<div class="sdp-daily-panel"><div class="sdp-daily-panel-head"><div><h3><i class="fa fa-check-square-o"></i> Today's Checklist</h3><p>Check each task as soon as you finish it. Tomorrow starts with a fresh checklist.</p></div><form method="get" action="<?php echo admin_url('smart_daily_productivity/checklist'); ?>"><label for="sdp-date">View date</label><input id="sdp-date" type="date" name="date" value="<?php echo html_escape($date); ?>" onchange="this.form.submit()" class="form-control"></form></div>
<div class="sdp-daily-progress"><div style="width:<?php echo $percent; ?>%"></div></div>
<?php foreach($active as $x): $done=isset($checked[(int)$x['id']]); ?><form method="post" action="<?php echo admin_url('smart_daily_productivity/checklist?date='.urlencode($date)); ?>" class="sdp-daily-task <?php echo $done?'done':''; ?>"><?php echo form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()); ?><input type="hidden" name="action" value="check"><input type="hidden" name="id" value="<?php echo (int)$x['id']; ?>"><input type="hidden" name="checked" value="<?php echo $done?'0':'1'; ?>"><button type="submit" class="sdp-daily-checkbox" aria-label="<?php echo $done?'Mark not done':'Mark completed'; ?>: <?php echo html_escape($x['title']); ?>"><i class="fa <?php echo $done?'fa-check-square':'fa-square-o'; ?>"></i></button><div class="sdp-daily-task-copy"><strong><?php echo html_escape($x['title']); ?></strong><?php if(trim($x['notes'])!==''): ?><p><?php echo nl2br(html_escape($x['notes'])); ?></p><?php endif; ?></div><span class="sdp-daily-state"><?php echo $done?'Done':'To do'; ?></span></form><?php endforeach; ?>
<?php if(!$total): ?><div class="sdp-daily-empty"><i class="fa fa-list-alt"></i><h4>No daily tasks assigned yet</h4><p>Add recurring tasks in Manage Daily Tasks. They will appear here automatically every day.</p><a class="btn btn-primary" href="<?php echo admin_url('smart_daily_productivity/manage_tasks'); ?>">Manage Daily Tasks</a></div><?php endif; ?>
<div class="sdp-daily-bottom"><a class="btn btn-default" href="<?php echo admin_url('smart_daily_productivity/manage_tasks'); ?>"><i class="fa fa-cog"></i> Manage Daily Tasks</a><a class="btn btn-success" href="<?php echo admin_url('smart_daily_productivity/my_day'); ?>"><i class="fa fa-send"></i> Submit Daily Report</a></div></div></div></div></div>
